# ตัด placeholder ออก
DATA["mbti"] = [t for t in DATA["mbti"] if t[0] != "mbti-isfj-placeholder"]

count = 0
per_fw = {}
for fw, items in DATA.items():
    d = os.path.join(BASE, fw)
    os.makedirs(d, exist_ok=True)
    per_fw[fw] = 0
    for slug, label, traits, comm, avoid, mot, fb, pers, conf in items:
        with open(os.path.join(d, slug + ".md"), "w", encoding="utf-8") as f:
            f.write(md(slug, fw, label, traits, comm, avoid, mot, fb, pers, conf))
        count += 1
        per_fw[fw] += 1

print(f"สร้าง people-skills: {count} ไฟล์")
for fw, n in per_fw.items():
    print(f"  {fw}: {n}")
